static String strEscape(String s, char quote,
                          String doublequoteEscape,
                          String singlequoteEscape,
                          String backslashEscape,
                          CharsetEncoder outputCharsetEncoder) {
    StringBuilder sb = new StringBuilder(s.length() + 2);
    sb.append(quote);
    for (int i = 0; i < s.length(); ) {
        int cp = s.codePointAt(i);
        // Determine if we are dealing with a surrogate pair
        boolean isSurrogate = cp > 0xFFFF;
        char c = (char) cp; // safe for BMP characters
        switch (c) {
            case '\0':
                sb.append("\\0");
                break;
            case '\n':
                sb.append("\\n");
                break;
            case '\r':
                sb.append("\\r");
                break;
            case '\t':
                sb.append("\\t");
                break;
            case '\\':
                sb.append(backslashEscape);
                break;
            case '\"':
                sb.append(doublequoteEscape);
                break;
            case '\'':
                sb.append(singlequoteEscape);
                break;
            case '>':
                // Break --> into --\> or ]]> into ]]\>
                if (i >= 2 &&
                    ((s.charAt(i - 1) == '-' && s.charAt(i - 2) == '-') ||
                     (s.charAt(i - 1) == ']' && s.charAt(i - 2) == ']'))) {
                    sb.append("\\>");
                } else {
                    sb.append(c);
                }
                break;
            case '<':
                // Break </script into <\/script
                final String END_SCRIPT = "/script";
                // Break <!-- into <\!--
                final String START_COMMENT = "!--";
                if (s.regionMatches(true, i + 1, END_SCRIPT, 0, END_SCRIPT.length())) {
                    sb.append("<\\");
                } else if (s.regionMatches(false, i + 1, START_COMMENT, 0, START_COMMENT.length())) {
                    sb.append("<\\");
                } else {
                    sb.append(c);
                }
                break;
            default:
                if (isSurrogate) {
                    // For characters outside BMP, always Unicode‑escape
                    try {
                        appendHexJavaScriptRepresentation(cp, sb);
                    } catch (IOException e) {
                        // This should never happen with StringBuilder
                        throw new RuntimeException(e);
                    }
                } else if (outputCharsetEncoder != null) {
                    if (outputCharsetEncoder.canEncode(c)) {
                        sb.append(c);
                    } else {
                        appendHexJavaScriptRepresentation(sb, c);
                    }
                } else {
                    if (c > 0x1f && c <= 0x7f) {
                        sb.append(c);
                    } else {
                        appendHexJavaScriptRepresentation(sb, c);
                    }
                }
                break;
        }
        i += Character.charCount(cp);
    }
    sb.append(quote);
    return sb.toString();
}
